@Test
public void testPOSTaggerWithCustomFactory() throws Exception {
    Path dictionary = POSDictionayBuilderTest.createMorfologikDictionary();
    dictionary.toFile().deleteOnExit();
    POSTaggerFactory inFactory = new MorfologikPOSTaggerFactory();
    TagDictionary inDict = inFactory.createTagDictionary(dictionary.toFile());
    inFactory.setTagDictionary(inDict);
    POSModel posModel = trainPOSModel(ModelType.MAXENT, inFactory);
    POSTaggerFactory factory = posModel.getFactory();
    Assert.assertTrue(factory.getTagDictionary() instanceof MorfologikTagDictionary);
    factory = null;
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    posModel.serialize(out);
    ByteArrayInputStream in = new ByteArrayInputStream(out.toByteArray());
    POSModel fromSerialized = new POSModel(in);
    factory = fromSerialized.getFactory();
    Assert.assertTrue(factory.getTagDictionary() instanceof MorfologikTagDictionary);
    Assert.assertEquals(2, factory.getTagDictionary().getTags("casa").length);
}

@Test
public void testEvaluator() throws IOException {
    ResourceAsStreamFactory inPredicted = new ResourceAsStreamFactory(getClass(), "/opennlp/tools/chunker/output.txt");
    ResourceAsStreamFactory inExpected = new ResourceAsStreamFactory(getClass(), "/opennlp/tools/chunker/output.txt");
    ResourceAsStreamFactory detailedOutputStream = new ResourceAsStreamFactory(getClass(), "/opennlp/tools/chunker/detailedOutput.txt");
    DummyChunkSampleStream predictedSample = new DummyChunkSampleStream(new PlainTextByLineStream(inPredicted, StandardCharsets.UTF_8), true);
    DummyChunkSampleStream expectedSample = new DummyChunkSampleStream(new PlainTextByLineStream(inExpected, StandardCharsets.UTF_8), false);
    Chunker dummyChunker = new DummyChunker(predictedSample);
    ChunkerDetailedFMeasureListener listener = new ChunkerDetailedFMeasureListener();
    ChunkerEvaluator evaluator = new ChunkerEvaluator(dummyChunker, listener);
    evaluator.evaluate(expectedSample);
    StringBuilder expected = new StringBuilder();
    BufferedReader reader = new BufferedReader(new InputStreamReader(detailedOutputStream.createInputStream(), StandardCharsets.UTF_8));
    String line = reader.readLine();
    while (line != null) {
        expected.append(line);
        expected.append("\n");
        line = reader.readLine();
    }
    Assert.assertEquals(expected.toString().trim(), listener.createReport(Locale.ENGLISH).trim());
}

/**
 * Checks the evaluator results against the results got using the conlleval,
 * available at http://www.cnts.ua.ac.be/conll2000/chunking/output.html
 * The output.txt file has only 3 sentences, but can be replaced by the one
 * available at the conll2000 site to validate using a bigger sample.
 *
 * @throws IOException
 */
@Test
public void testEvaluator() throws IOException {
    ResourceAsStreamFactory inPredicted = new ResourceAsStreamFactory(getClass(), "/opennlp/tools/chunker/output.txt");
    ResourceAsStreamFactory inExpected = new ResourceAsStreamFactory(getClass(), "/opennlp/tools/chunker/output.txt");
    DummyChunkSampleStream predictedSample = new DummyChunkSampleStream(new PlainTextByLineStream(inPredicted, StandardCharsets.UTF_8), true);
    DummyChunkSampleStream expectedSample = new DummyChunkSampleStream(new PlainTextByLineStream(inExpected, StandardCharsets.UTF_8), false);
    Chunker dummyChunker = new DummyChunker(predictedSample);
    OutputStream stream = new ByteArrayOutputStream();
    ChunkerEvaluationMonitor listener = new ChunkEvaluationErrorListener(stream);
    ChunkerEvaluator evaluator = new ChunkerEvaluator(dummyChunker, listener);
    evaluator.evaluate(expectedSample);
    FMeasure fm = evaluator.getFMeasure();
    Assert.assertEquals(0.8d, fm.getPrecisionScore(), DELTA);
    Assert.assertEquals(0.875d, fm.getRecallScore(), DELTA);
    Assert.assertNotSame(stream.toString().length(), 0);
}

