    Files.copy(new File(getOpennlpDataDir(), "models-sf/en-pos-perceptron.bin").toPath(), new File(resourcesPath.toFile(), "en-pos-perceptron.bin").toPath(), StandardCopyOption.REPLACE_EXISTING);
    Map<String, Object> resources = TokenNameFinderTrainerTool.loadResources(resourcesPath.toFile(), Paths.get(this.getClass().getResource("ner-en_pos-features.xml").toURI()).toFile());
    try (ObjectStream<NameSample> samples = createNameSampleStream()) {
        TokenNameFinderCrossValidator cv = new TokenNameFinderCrossValidator("eng", null, params, featureGen, resources);
        ObjectStream<NameSample> filteredSamples;
        filteredSamples = samples;
        cv.evaluate(filteredSamples, 5);
