    double[] eval02 = deserModel.eval(features2Classify);
    Assert.assertEquals(eval01.length, eval02.length);
    for (int i = 0; i < eval01.length; i++) {
        Assert.assertEquals(eval01[i], eval02[i], 0.00000001);
    }
}

@Test
public void testRealValuedWeightsVsRepeatWeighting() throws IOException {
    GISModel realModel;
    GISTrainer gisTrainer = new GISTrainer();
    try (RealValueFileEventStream rvfes1 = new RealValueFileEventStream("src/test/resources/data/opennlp/maxent/real-valued-weights-training-data.txt")) {
        testDataIndexer.index(rvfes1);
        realModel = gisTrainer.trainModel(100, testDataIndexer);
    }
    GISModel repeatModel;
    try (FileEventStream rvfes2 = new FileEventStream("src/test/resources/data/opennlp/maxent/repeat-weighting-training-data.txt")) {
        testDataIndexer.index(rvfes2);
        repeatModel = gisTrainer.trainModel(100, testDataIndexer);
    }
    String[] features2Classify = new String[] { "feature2", "feature5" };
    double[] realResults = realModel.eval(features2Classify);
    double[] repeatResults = repeatModel.eval(features2Classify);
    Assert.assertEquals(realResults.length, repeatResults.length);
    for (int i = 0; i < realResults.length; i++) {
        System.out.println(String.format("classifiy with realModel: %1$s = %2$f", realModel.getOutcome(i), realResults[i]));
        System.out.println(String.format("classifiy with repeatModel: %1$s = %2$f", repeatModel.getOutcome(i), repeatResults[i]));
        Assert.assertEquals(realResults[i], repeatResults[i], 0.01f);
    }
    features2Classify = new String[] { "feature1", "feature2", "feature3", "feature4", "feature5" };
    realResults = realModel.eval(features2Classify, new float[] { 5.5f, 6.1f, 9.1f, 4.0f, 1.8f });
    repeatResults = repeatModel.eval(features2Classify, new float[] { 5.5f, 6.1f, 9.1f, 4.0f, 1.8f });
    System.out.println();
    Assert.assertEquals(realResults.length, repeatResults.length);
    for (int i = 0; i < realResults.length; i++) {
        System.out.println(String.format("classifiy with realModel: %1$s = %2$f", realModel.getOutcome(i), realResults[i]));
        System.out.println(String.format("classifiy with repeatModel: %1$s = %2$f", repeatModel.getOutcome(i), repeatResults[i]));
        Assert.assertEquals(realResults[i], repeatResults[i], 0.01f);
    }
}

/**
 * This test sets out to prove that the scale you use on real valued
 * predicates doesn't matter when it comes the probability assigned to each
 * outcome. Strangely, if we use (1,2) and (10,20) there's no difference. If
 * we use (0.1,0.2) and (10,20) there is a difference.
 */
@Test
public void testScaleResults() throws Exception {
    String smallValues = "predA=0.1 predB=0.2 A\n" + "predB=0.3 predA=0.1 B\n";
    String smallTest = "predA=0.2 predB=0.2";
    String largeValues = "predA=10 predB=20 A\n" + "predB=30 predA=10 B\n";
    String largeTest = "predA=20 predB=20";
    ObjectStream<Event> smallEventStream = new RealBasicEventStream(new PlainTextByLineStream(new MockInputStreamFactory(smallValues), StandardCharsets.UTF_8));
    testDataIndexer.index(smallEventStream);
    EventTrainer smallModelTrainer = TrainerFactory.getEventTrainer(ModelUtil.createDefaultTrainingParameters(), null);
    MaxentModel smallModel = smallModelTrainer.train(testDataIndexer);
    String[] contexts = smallTest.split(" ");
    float[] values = RealValueFileEventStream.parseContexts(contexts);
    double[] smallResults = smallModel.eval(contexts, values);
    String smallResultString = smallModel.getAllOutcomes(smallResults);
    System.out.println("smallResults: " + smallResultString);
    ObjectStream<Event> largeEventStream = new RealBasicEventStream(new PlainTextByLineStream(new MockInputStreamFactory(largeValues), StandardCharsets.UTF_8));
    testDataIndexer.index(largeEventStream);
    EventTrainer largeModelTrainer = TrainerFactory.getEventTrainer(ModelUtil.createDefaultTrainingParameters(), null);
    MaxentModel largeModel = largeModelTrainer.train(testDataIndexer);
    contexts = largeTest.split(" ");
    values = RealValueFileEventStream.parseContexts(contexts);
    double[] largeResults = largeModel.eval(contexts, values);
    String largeResultString = largeModel.getAllOutcomes(largeResults);
    System.out.println("largeResults: " + largeResultString);
    Assert.assertEquals(smallResults.length, largeResults.length);
    for (int i = 0; i < smallResults.length; i++) {
        System.out.println(String.format("classifiy with smallModel: %1$s = %2$f", smallModel.getOutcome(i), smallResults[i]));
        System.out.println(String.format("classifiy with largeModel: %1$s = %2$f", largeModel.getOutcome(i), largeResults[i]));
        Assert.assertEquals(smallResults[i], largeResults[i], 0.01f);
    }
}

