@Test
public void testNameFinder() throws Exception {
    // train the name finder
    String encoding = "ISO-8859-1";
    ObjectStream<NameSample> sampleStream = new NameSampleDataStream(new PlainTextByLineStream(new MockInputStreamFactory(new File("opennlp/tools/namefind/AnnotatedSentences.txt")), encoding));
    TrainingParameters params = new TrainingParameters();
    params.put(TrainingParameters.ITERATIONS_PARAM, 70);
    params.put(TrainingParameters.CUTOFF_PARAM, 1);
    TokenNameFinderModel nameFinderModel = NameFinderME.train("eng", null, sampleStream, params, TokenNameFinderFactory.create(null, null, Collections.emptyMap(), new BioCodec()));
    TokenNameFinder nameFinder = new NameFinderME(nameFinderModel);
    // now test if it can detect the sample sentences
    String[] sentence = { "Alisa", "appreciated", "the", "hint", "and", "enjoyed", "a", "delicious", "traditional", "meal." };
    Span[] names = nameFinder.find(sentence);
    Assert.assertEquals(1, names.length);
    Assert.assertEquals(new Span(0, 1, DEFAULT), names[0]);
    sentence = new String[] { "Hi", "Mike", ",", "it's", "Stefanie", "Schmidt", "." };
    names = nameFinder.find(sentence);
    Assert.assertEquals(2, names.length);
    Assert.assertEquals(new Span(1, 2, DEFAULT), names[0]);
    Assert.assertEquals(new Span(4, 6, DEFAULT), names[1]);
}

