public void noDictionaryMatch() {
    int index = 1;
    final String[] actual = defaultPOSContextGenerator.getContext(index, tokens, tags);
    final String[] expected = new String[] { "default", "w=tokenB", "suf=B", "suf=nB", "suf=enB", "suf=kenB", "pre=t", "pre=to", "pre=tok", "pre=toke", "c", "p=tokenA", "t=tagA", "pp=*SB*", "n=tokenC", "nn=tokenD" };
    Assert.assertArrayEquals("Calling with not matching index at: " + index + "\nexpected \n" + Arrays.toString(expected) + " but actually was \n" + Arrays.toString(actual), expected, actual);
}

@Test
public void dictionaryMatch() {
    int indexWithDictionaryMatch = 2;
    final String[] actual = defaultPOSContextGenerator.getContext(indexWithDictionaryMatch, tokens, tags);
    final String[] expected = new String[] { "default", "w=tokenC", "p=tokenB", "t=tagB", "pp=tokenA", "t2=tagA,tagB", "n=tokenD", "nn=*SE*" };
    Assert.assertArrayEquals("Calling with index matching dictionary entry at: " + indexWithDictionaryMatch + "\nexpected \n" + Arrays.toString(expected) + " but actually was \n" + Arrays.toString(actual), expected, actual);
}

@Test
public void multithreading() {
    Callable<Void> matching = () -> {
        dictionaryMatch();
        return null;
    };
    Callable<Void> notMatching = () -> {
        noDictionaryMatch();
        return null;
    };
    final List<Callable<Void>> callables = IntStream.range(0, 200000).mapToObj(index -> (index % 2 == 0) ? matching : notMatching).collect(Collectors.toList());
    final ExecutorService executorService = Executors.newFixedThreadPool(NUMBER_OF_THREADS);
    try {
        final List<Future<Void>> futures = executorService.invokeAll(callables);
        executorService.shutdown();
        executorService.awaitTermination(30, TimeUnit.SECONDS);
        futures.forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException e) {
                Assert.fail("Interrupted because of: " + e.getCause().getMessage());
            } catch (ExecutionException ee) {
                Assert.fail(ee.getCause().getMessage());
            }
        });
    } catch (final InterruptedException e) {
        Assert.fail("Test interrupted");
    }
}

